 */
private void persistOutcome(RouteSubmitRequest request, String inputHash,
                            MatchOutcome outcome, OffsetDateTime createdAt) {
    List<RouteCandidateRow> rows = new ArrayList<>();
    appendCandidateRows(request.requestId(), "START", outcome.startCandidates(), rows);
    appendCandidateRows(request.requestId(), "END", outcome.endCandidates(), rows);
    try {
        routeRepository.insertCandidates(request.requestId(), rows);
    } catch (DuplicateKeyException ignored) {
        // 竞争事务已写入候选明细时不重复插入，随后 insertRequest 的唯一冲突会走重放分支
        return;
    }
    if (outcome.matched()) {
        routeRepository.insertMatch(new RouteMatchRow(
                request.requestId(),
                outcome.selectedStartSegmentId(),
                outcome.selectedEndSegmentId(),
                JsonLists.writeStringList(outcome.pathNodeIds()),
                JsonLists.writeStringList(outcome.pathSegmentIds()),
                outcome.totalScore()));
    }
}

