/**
 * 发布载荷拓扑校验：节点/路段 ID 不重复，路段引用端点存在，长度缺省按几何计算。
 */
private void validateTopology(PublishMapRequest request) {
    Set<String> nodeIds = new HashSet<>();
    for (PublishMapRequest.NodeSpec node : request.nodes()) {
        if (!nodeIds.add(node.nodeId())) {
            throw new ApiException(ErrorCode.MAP_TOPOLOGY_INVALID,
                    "端点 ID 重复: " + node.nodeId());
        }
    }
    Set<String> segmentIds = new HashSet<>();
    for (PublishMapRequest.SegmentSpec segment : request.segments()) {
        if (!segmentIds.add(segment.segmentId())) {
            throw new ApiException(ErrorCode.MAP_TOPOLOGY_INVALID,
                    "路段 ID 重复: " + segment.segmentId());
        }
        if (!nodeIds.contains(segment.fromNodeId())) {
            throw new ApiException(ErrorCode.MAP_TOPOLOGY_INVALID,
                    "路段 " + segment.segmentId() + " 引用了不存在的起点端点: " + segment.fromNodeId());
        }
        if (!nodeIds.contains(segment.toNodeId())) {
            throw new ApiException(ErrorCode.MAP_TOPOLOGY_INVALID,
                    "路段 " + segment.segmentId() + " 引用了不存在的终点端点: " + segment.toNodeId());
        }
        if (segment.lengthM() == null) {
            PublishMapRequest.NodeSpec from = findNode(request.nodes(), segment.fromNodeId());
            PublishMapRequest.NodeSpec to = findNode(request.nodes(), segment.toNodeId());
            double computed = Math.hypot(to.x() - from.x(), to.y() - from.y());
            // 用计算长度替换载荷中的 null，避免落库空值
            request.segments().set(request.segments().indexOf(segment),
                    new PublishMapRequest.SegmentSpec(segment.segmentId(),
                            segment.fromNodeId(), segment.toNodeId(), computed, segment.valid()));
        }
    }
}

private static PublishMapRequest.NodeSpec findNode(List<PublishMapRequest.NodeSpec> nodes,
                                                   String nodeId) {
    return nodes.stream().filter(n -> n.nodeId().equals(nodeId)).findFirst().orElseThrow();
}

