            .filter(c -> c.segmentId().equals("s2")).findFirst().orElseThrow();
    assertTrue(deadEnd.rejectReasons().contains("NOT_CONNECTED"));
    assertEquals(0.0, deadEnd.connectivityScore(), 0.0);
    assertFalse(deadEnd.selected());
}

