42	    public MatchOutcome match(MapSnapshot snapshot, RouteSubmitRequest.PointInput start,
43	                              RouteSubmitRequest.PointInput end) {
44	        List<RawCandidate> startRaws = buildCandidates(snapshot, start);
45	        List<RawCandidate> endRaws = buildCandidates(snapshot, end);
46	
47	        if (startRaws.isEmpty()) {
48	            return failed("START_NO_CANDIDATE", startRaws, endRaws);
49	        }
50	        if (endRaws.isEmpty()) {
51	            return failed("END_NO_CANDIDATE", startRaws, endRaws);
52	        }
53	
54	        List<RawCandidate> startValid = startRaws.stream().filter(r -> r.segment.valid()).toList();
55	        List<RawCandidate> endValid = endRaws.stream().filter(r -> r.segment.valid()).toList();
56	        if (startValid.isEmpty() || endValid.isEmpty()) {
57	            return failed("SEGMENT_INVALID", startRaws, endRaws);
58	        }
59	
60	        // 仅有效路段构成有向图：node -> 出边（按路段 ID 排序保证遍历确定性）
61	        Map<String, List<Edge>> adjacency = buildAdjacency(snapshot);
62	
63	        // 为每个有效起点候选计算可达节点集合，得到全部连通候选对
64	        Map<String, Set<String>> reachableFromStart = new HashMap<>();
65	        for (RawCandidate s : startValid) {
66	            reachableFromStart.put(s.segment.segmentId(),
67	                    reachableNodes(s.segment.toNodeId(), adjacency));
68	        }
69	        List<CandidatePair> connectedPairs = new ArrayList<>();
70	        for (RawCandidate s : startValid) {
71	            Set<String> reachable = reachableFromStart.get(s.segment.segmentId());
72	            for (RawCandidate e : endValid) {
73	                // 起终点落在同一有效路段，或起点路段终点可达终点路段起点，均视为连通
74	                if (s.segment.segmentId().equals(e.segment.segmentId())
75	                        || reachable.contains(e.segment.fromNodeId())) {
76	                    connectedPairs.add(new CandidatePair(s, e, s.baseScore() + e.baseScore()));
77	                }
78	            }
79	        }
80	        if (connectedPairs.isEmpty()) {
81	            return failed("PATH_DISCONNECTED", startRaws, endRaws);
82	        }
