tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
}

// Windows 下工作目录可能含非 ASCII 字符，过长的测试类路径会触发 @argfile，
// 而 argfile 被系统 ANSI 码页误读后会使 worker 类路径损坏（GradleWorkerMain 找不到）。
// 用仅含清单 Class-Path 的 pathing jar 承载完整测试类路径：清单条目经百分号编码为纯 ASCII，
// worker 命令行只剩一个短条目，从而避免 argfile 编码问题。
def testPathingJar = tasks.register('testPathingJar', Jar) {
    archiveFileName = 'test-pathing.jar'
    manifest {
        attributes(
            'Class-Path': sourceSets.test.runtimeClasspath.files.collect {
                it.toURI().toASCIIString()
            }.join(' ')
        )
    }
}

tasks.named('test') {
    useJUnitPlatform()
    dependsOn testPathingJar
    classpath = files(testPathingJar.flatMap { it.archiveFile })
    testLogging {
        events 'passed', 'skipped', 'failed'
        exceptionFormat = 'full'
    }
}

